<?php
declare(strict_types=1);namespace Joomleague\Component\Joomleague\Domain\Service;defined('_JEXEC')or die;use Joomla\Database\DatabaseInterface;use Joomla\Database\ParameterType;
final class VenueSummaryReader{public function __construct(private readonly DatabaseInterface$db){}/** @param list<int>$viewLevels @return array<string,mixed> */public function read(int$id,array$viewLevels):array{if($id<1)return['error'=>'venue_required'];$levels=array_values(array_unique(array_filter(array_map('intval',$viewLevels),static fn(int$i):bool=>$i>0)));$access=implode(',',$levels?:[1]);$v=$this->db->setQuery($this->db->getQuery(true)->select(['venue.id','venue.name','venue.short_name','venue.nickname','venue.address','venue.postal_code','venue.city','venue.region','venue.country_code','venue.latitude','venue.longitude','venue.timezone','venue.capacity','venue.website','venue.picture','venue.description','club.id AS club_id','club.name AS club_name'])->from($this->db->quoteName('#__joomleague_venue','venue'))->leftJoin($this->db->quoteName('#__joomleague_club','club').' ON club.id=venue.owner_club_id AND club.published=1 AND club.access IN ('.$access.')')->where('venue.id=:venueId')->where('venue.published=1')->where('venue.access IN ('.$access.')')->bind(':venueId',$id,ParameterType::INTEGER))->loadObject();return$v?['venue'=>$v]:['error'=>'venue_unavailable'];}}
